import os
import hashlib
import hmac
import re
from pathlib import PurePosixPath
from functools import wraps

# Role-based access control for monitoring agent
ROLES = {
    "admin": {"read_logs", "write_logs", "configure", "read_metrics"},
    "operator": {"read_logs", "read_metrics"},
    "viewer": {"read_metrics"}
}

LOG_BASE_DIR = "/var/log/monitoring"
ALLOWED_EXTENSIONS = {".log", ".txt", ".json", ".csv"}

class AuthToken:
    def __init__(self, username, role, secret_key):
        self.username = username
        self.role = role
        self.signature = hmac.new(
            secret_key.encode(),
            f"{username}:{role}".encode(),
            hashlib.sha256
        ).hexdigest()

    def verify(self, secret_key):
        expected = hmac.new(
            secret_key.encode(),
            f"{self.username}:{self.role}".encode(),
            hashlib.sha256
        ).hexdigest()
        return hmac.compare_digest(self.signature, expected)


def require_permission(permission):
    def decorator(func):
        @wraps(func)
        def wrapper(self, token, *args, **kwargs):
            if not token.verify(self.secret_key):
                raise PermissionError("Invalid authentication token")
            role_perms = ROLES.get(token.role, set())
            if permission not in role_perms:
                raise PermissionError(
                    f"Role '{token.role}' lacks permission '{permission}'"
                )
            return func(self, token, *args, **kwargs)
        return wrapper
    return decorator


class PathValidator:
    """Validates and normalizes file paths to prevent traversal attacks."""

    def __init__(self, base_directory):
        self.base_directory = os.path.realpath(base_directory)

    def _normalize_path_component(self, component):
        """Remove potentially dangerous characters from path components."""
        # Strip null bytes and control characters
        cleaned = re.sub(r'[\x00-\x1f]', '', component)
        return cleaned

    def _resolve_symbolic_segments(self, path_str):
        """Resolve '..' and '.' segments in a platform-independent way."""
        parts = PurePosixPath(path_str).parts
        resolved = []
        for part in parts:
            if part == '..':
                if resolved:
                    resolved.pop()
            elif part != '.' and part != '/':
                resolved.append(self._normalize_path_component(part))
        return '/'.join(resolved)

    def validate(self, requested_path):
        """Validate that the requested path stays within base directory.

        Returns the safe absolute path or raises ValueError.
        """
        # Step 1: Normalize the user-provided relative path
        normalized = self._resolve_symbolic_segments(requested_path)

        # Step 2: Construct the candidate absolute path
        candidate = os.path.join(self.base_directory, normalized)

        # Step 3: Resolve to real path (follows symlinks)
        real_candidate = os.path.realpath(candidate)

        # Step 4: Verify the resolved path is under base directory
        if not real_candidate.startswith(self.base_directory):
            raise ValueError(
                f"Path traversal detected: '{requested_path}' resolves outside base"
            )

        # Step 5: Check file extension
        _, ext = os.path.splitext(real_candidate)
        if ext and ext not in ALLOWED_EXTENSIONS:
            raise ValueError(f"File extension '{ext}' not allowed")

        return real_candidate


class MonitoringAgent:
    def __init__(self, secret_key, log_base=LOG_BASE_DIR):
        self.secret_key = secret_key
        self.log_base = log_base
        self.path_validator = PathValidator(log_base)
        self._ensure_base_exists()

    def _ensure_base_exists(self):
        os.makedirs(self.log_base, exist_ok=True)

    @require_permission("read_logs")
    def read_log_file(self, token, relative_path, offset=0, limit=1024):
        """Read a log file with pagination support."""
        safe_path = self.path_validator.validate(relative_path)

        if not os.path.isfile(safe_path):
            raise FileNotFoundError(f"Log file not found: {relative_path}")

        with open(safe_path, 'r', encoding='utf-8', errors='replace') as f:
            f.seek(offset)
            content = f.read(limit)

        return {
            "path": relative_path,
            "offset": offset,
            "length": len(content),
            "content": content
        }

    @require_permission("read_logs")
    def list_log_directory(self, token, relative_dir=""):
        """List files in a log subdirectory."""
        safe_path = self.path_validator.validate(relative_dir)

        if not os.path.isdir(safe_path):
            raise NotADirectoryError(f"Not a directory: {relative_dir}")

        entries = []
        for entry in os.scandir(safe_path):
            entries.append({
                "name": entry.name,
                "is_dir": entry.is_dir(),
                "size": entry.stat().st_size if entry.is_file() else 0
            })
        return entries

    @require_permission("read_metrics")
    def get_agent_status(self, token):
        """Return agent health metrics."""
        return {
            "status": "healthy",
            "log_base": self.log_base,
            "uptime_seconds": self._get_uptime()
        }

    def _get_uptime(self):
        try:
            with open('/proc/uptime', 'r') as f:
                return float(f.read().split()[0])
        except (IOError, ValueError):
            return -1


# Request handler for the monitoring agent HTTP interface
def handle_read_request(agent, auth_header, params):
    """Process an authenticated log read request."""
    token = _parse_auth_header(auth_header, agent.secret_key)

    file_path = params.get("path", "")
    offset = int(params.get("offset", 0))
    limit = min(int(params.get("limit", 4096)), 65536)

    return agent.read_log_file(token, file_path, offset=offset, limit=limit)


def _parse_auth_header(header, secret_key):
    """Parse 'username:role:signature' auth header."""
    parts = header.split(':')
    if len(parts) != 3:
        raise ValueError("Malformed auth header")
    token = AuthToken.__new__(AuthToken)
    token.username = parts[0]
    token.role = parts[1]
    token.signature = parts[2]
    return token
